-- reset identity sequences past the explicitly-inserted ids

SELECT setval(pg_get_serial_sequence('brands', 'brand_id'), (SELECT MAX(brand_id) FROM brands));
SELECT setval(pg_get_serial_sequence('categories', 'category_id'), (SELECT MAX(category_id) FROM categories));
SELECT setval(pg_get_serial_sequence('stores', 'store_id'), (SELECT MAX(store_id) FROM stores));
SELECT setval(pg_get_serial_sequence('staffs', 'staff_id'), (SELECT MAX(staff_id) FROM staffs));
SELECT setval(pg_get_serial_sequence('customers', 'customer_id'), (SELECT MAX(customer_id) FROM customers));
SELECT setval(pg_get_serial_sequence('products', 'product_id'), (SELECT MAX(product_id) FROM products));
SELECT setval(pg_get_serial_sequence('orders', 'order_id'), (SELECT MAX(order_id) FROM orders));

-- turn output back on just for a final one-line proof that seeding worked
\set QUIET off
SELECT
    (SELECT count(*) FROM brands)      AS brands,
    (SELECT count(*) FROM categories)  AS categories,
    (SELECT count(*) FROM stores)      AS stores,
    (SELECT count(*) FROM staffs)      AS staffs,
    (SELECT count(*) FROM customers)   AS customers,
    (SELECT count(*) FROM products)    AS products,
    (SELECT count(*) FROM orders)      AS orders,
    (SELECT count(*) FROM order_items) AS order_items,
    (SELECT count(*) FROM stocks)      AS stocks,
    (SELECT count(*) FROM users)       AS users;
\echo 'Seed data loaded successfully.'
